const art={a:['maps/warm-studio-v1.png','Warm studio office map treatment'],b:['maps/cool-workroom-v1.png','Cool workroom office map treatment'],c:['maps/editorial-room-v1.png','Editorial room office map treatment']};const room=document.querySelector('#room'),player=document.querySelector('#player'),panel=document.querySelector('#panel'),inbox=document.querySelector('#inbox'),decision=document.querySelector('#decision-dialog');let pos={x:47,y:59};
document.querySelectorAll('[data-map]').forEach(b=>b.onclick=()=>{const [src,alt]=art[b.dataset.map];document.querySelector('#room-art').src=src;document.querySelector('#room-art').alt=alt;document.querySelectorAll('[data-map]').forEach(x=>x.classList.toggle('active',x===b));room.focus()});
function open(a){if(a==='inbox')return inbox.showModal();if(a==='decision'||a==='meeting')return decision.showModal();panel.hidden=false;const surface=panel.querySelector('.panel-surface');surface.classList.remove('panel-enter');void surface.offsetWidth;surface.classList.add('panel-enter')}document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>open(b.dataset.action));document.querySelector('#inbox-button').onclick=()=>open('inbox');document.querySelectorAll('.close').forEach(b=>b.onclick=()=>b.closest('dialog')?.close()||(panel.hidden=true));
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-view]').forEach(x=>x.classList.toggle('active',x===b));document.querySelector('.conversation').hidden=b.dataset.view==='terminal';document.querySelector('#terminal').hidden=b.dataset.view!=='terminal'});document.querySelector('#motion').onclick=e=>{document.body.classList.toggle('reduced');e.currentTarget.textContent=document.body.classList.contains('reduced')?'Motion: reduced':'Motion: on'};
room.onkeydown=e=>{const m={ArrowLeft:[-3,0],a:[-3,0],ArrowRight:[3,0],d:[3,0],ArrowUp:[0,-3],w:[0,-3],ArrowDown:[0,3],s:[0,3]};const map={1:'a',2:'b',3:'c'}[e.key];if(map){document.querySelector(`[data-map="${map}"]`).click();return}if(e.key.toLowerCase()==='e')return open('employee');const v=m[e.key]||m[e.key.toLowerCase()];if(!v)return;e.preventDefault();pos.x=Math.max(4,Math.min(88,pos.x+v[0]));pos.y=Math.max(8,Math.min(87,pos.y+v[1]));player.style.left=`${pos.x}%`;player.style.top=`${pos.y}%`};
const history=document.querySelector('#decision-history');
const feedback=document.querySelector('#feedback');
function addRevision(note){const version=history.querySelectorAll('p').length+1;history.insertAdjacentHTML('beforeend',`<p><b>You · feedback</b><br>${note}</p><p class="bubble-enter"><b>Rowan · proposal v${version}</b><br>I’ll revise around that input and return a new version for review. Nothing has been approved.</p>`);feedback.value='';}
document.querySelectorAll('[data-choice]').forEach(button=>button.onclick=()=>addRevision(`Explore ${button.dataset.choice}, but keep this open for revision.`));
document.querySelector('#request-revision').onclick=()=>addRevision(feedback.value.trim()||'I need a different option before choosing.');
